  const GEMS = [{"id": "gem-persille", "pattern": "jambon persillé", "tag": "Burgundy gem · born here", "name": "The Easter terrine", "story": "Jambon persillé is ham cooked in white wine, torn and set in a jelly thick with parsley: Burgundy's dish for Easter. On rue Monge the charcutier sells it by the slice all year, to eat standing with bread and a cornichon.", "where": "The charcutiers of rue and Place Monge; the Saturday market."}, {"id": "gem-meurette", "pattern": "meurette", "tag": "Burgundy gem · born here", "name": "The wine is the sauce", "story": "A meurette is red wine reduced with shallots, lardons and mushrooms until it coats a spoon. Poured over poached eggs it becomes the first course of every bouchon on the Côte, and the plainest proof that this kitchen cooks with its wine.", "where": "The bouchons inside the ramparts."}, {"id": "gem-epoisses", "pattern": "Époisses", "tag": "Auxois gem · born here", "name": "The cheese washed in marc", "story": "Époisses is washed through its ageing with brine and marc de Bourgogne, the brandy of the press, until its rind turns orange. Its making had nearly died out by the 1940s; one family brought it back at Époisses in the 1950s.", "where": "The village of Époisses, about an hour north-west; the cheese shops of the Place Carnot."}];
